CREATE TABLE promotion_packages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, price BIGINT NOT NULL CHECK(price>=0), duration_hours INTEGER NOT NULL CHECK(duration_hours>0), promotion_type promotion_type NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', effective_from TIMESTAMPTZ NOT NULL DEFAULT now(), effective_to TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE promotion_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), seller_id UUID NOT NULL REFERENCES users(id), product_id UUID NOT NULL REFERENCES products(id), package_id UUID NOT NULL REFERENCES promotion_packages(id), package_price_snapshot BIGINT NOT NULL CHECK(package_price_snapshot>=0), status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PAID','CANCELLED','EXPIRED')), idempotency_key TEXT UNIQUE, paid_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX promotion_orders_seller_idx ON promotion_orders(seller_id,created_at DESC);
